import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx]); idx += 1
    m = int(input[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    edge_info = []

    for i in range(m):
        u = int(input[idx]); idx += 1
        v = int(input[idx]); idx += 1
        c = input[idx]; idx += 1
        adj[u].append((v, i))
        adj[v].append((u, i))
        edge_info.append(c)

    def try_target(target_color):
        state = [0] * (n + 1)
        queue = deque()

        for i in range(1, n + 1):
            current_red_count = 0
            for v, e_idx in adj[i]:
                initial_is_red = (edge_info[e_idx] == 'R')
                if state[v] == 0:
                    pass
                else:
                    initial_is_red = not initial_is_red

                if initial_is_red:
                    current_red_count += 1

            target_is_red = (target_color == 'R')
            needed_parity = 0
            if target_is_red:
                needed_parity = current_red_count % 2
            else:
                needed_parity = (current_red_count + 1) % 2

            if needed_parity != 0:
                state[i] = 1
                queue.append(i)

        visited = [False] * (n + 1)
        for i in range(1, n + 1):
            if state[i] == 1:
                visited[i] = True

        while queue:
            u = queue.popleft()
            for v, e_idx in adj[u]:
                if not visited[v]:
                    state[v] = 1 - state[v]
                    visited[v] = True
                    queue.append(v)
                else:
                    if state[v] == state[u]:
                        pass

        final_moves = [i for i in range(1, n + 1) if state[i] == 1]

        for i in range(m):
            u, v, c = None, None, None
            for neighbor, e_idx in adj[edge_info.index(edge_info[i])]:
                if e_idx == i:
                    u = neighbor[0]
                    break
            u, v = None, None
            for neighbor, e_idx in adj[1]:
                if e_idx == i:
                    break

            u, v = None, None
            for node in range(1, n+1):
                for neighbor, e_idx in adj[node]:
                    if e_idx == i:
                        u, v = node, neighbor
                        break
                if u is not None:
                    break

            flips = state[u] + state[v]
            initial_is_red = (edge_info[i] == 'R')
            final_is_red = initial_is_red if flips % 2 == 0 else not initial_is_red

            if target_color == 'R' and not final_is_red:
                return None
            if target_color == 'B' and final_is_red:
                return None

        return final_moves

    res_r = try_target('R')
    res_b = try_target('B')

    if res_r is None and res_b is None:
        print(-1)
    elif res_r is None:
        print(len(res_b))
        print(" ".join(map(str, res_b)))
    elif res_b is None:
        print(len(res_r))
        print(" ".join(map(str, res_r)))
    else:
        if len(res_r) < len(res_b):
            print(len(res_r))
            print(" ".join(map(str, res_r)))
        else:
            print(len(res_b))
            print(" ".join(map(str, res_b)))

